import { createHash, randomUUID } from 'node:crypto';
import { LocalReadAccessEventV2, LocalReadTarget, WorkContext, newAuditLinkId, parseLocalReadEvent } from '../emr-contract/access-event';
import { freeze } from '../emr-contract/validation';
import type { RequestFacts } from '../emr-runtime/request-context';
import { LOCAL_READ_UNAVAILABLE } from './response-lifecycle';

export interface LocalReadSource {
  /** Generated by the server before it puts an access reference into the response. */
  eventId: string;
  target: Omit<LocalReadTarget, 'projectionSha256'>;
  managingInstitution: string;
  /** Path in the serialized response to the exact portion this target provides. */
  path: readonly (string | number)[];
  /** Flattened responses can provide several records in one object. Hash only this record's returned fields. */
  fields?: readonly string[];
  cause: 'user-view' | 'background-fetch';
  context?: Readonly<WorkContext>;
}

/** Returned by A2/A3 after their existing source snapshot and authorization checks. */
export class LocalReadResponse {
  readonly json: string;
  readonly sources: readonly Readonly<LocalReadSource & { target: LocalReadTarget }>[];
  constructor(body: unknown, sources: readonly LocalReadSource[], readonly signal?: AbortSignal,
    readonly unavailable: Readonly<{ code: string; message: string }> = LOCAL_READ_UNAVAILABLE) {
    // Serialization happens once, before admission. toJSON, omitted fields and
    // serialization failures therefore describe the response we actually chose.
    const json = JSON.stringify(body);
    if (json === undefined) throw new Error('A local read needs a JSON response');
    const projection = JSON.parse(json);
    this.json = json;
    this.sources = freeze(sources.map(source => {
      let part = projection;
      for (const key of source.path) {
        if (part === null || typeof part !== 'object' || !Object.prototype.hasOwnProperty.call(part, key))
          throw new Error('Local read target is absent from the selected response');
        part = part[key];
      }
      if (source.fields) part = Object.fromEntries(source.fields.filter(key => Object.prototype.hasOwnProperty.call(part, key))
        .map(key => [key, part[key]]));
      return { ...structuredClone(source), target: { ...structuredClone(source.target),
        projectionSha256: createHash('sha256').update(JSON.stringify(part)).digest('hex') } };
    }));
    if (new Set(this.sources.map(s => s.eventId)).size !== this.sources.length) throw new Error('Duplicate local read event');
    Object.freeze(this);
  }
}

export function localReadEvents(facts: RequestFacts, response: LocalReadResponse): readonly Readonly<LocalReadAccessEventV2>[] {
  return Object.freeze(response.sources.map(source => parseLocalReadEvent({
    formatVersion: 2, branch: 'local-read', surface: facts.surface, eventId: source.eventId,
    userId: { status: 'known', value: facts.actor }, rolesAtTime: { status: 'known', value: facts.roles },
    rightsVersion: facts.rightsVersion, actingInstitution: { status: 'known', value: facts.institution },
    managingInstitution: { status: 'known', value: source.managingInstitution },
    occurredAt: new Date().toISOString(), trustedProxyIp: facts.ingress, session: facts.binding,
    cause: source.cause, context: source.context ?? null, executor: 'member', targets: [source.target], action: 'provide-prepared', result: 'prepared',
    requestId: facts.requestId, auditLinkId: newAuditLinkId(), relatedEventId: null,
  })));
}

export function localReadFollowup(prepared: LocalReadAccessEventV2, outcome: 'ended' | 'aborted'): Readonly<LocalReadAccessEventV2> {
  return parseLocalReadEvent({ ...prepared, eventId: randomUUID(), occurredAt: new Date().toISOString(),
    action: outcome === 'ended' ? 'transfer-ended' : 'transfer-aborted',
    result: outcome === 'ended' ? 'succeeded' : 'aborted', relatedEventId: prepared.eventId });
}
